//! Module: canic_core::diagnostics::codes
//!
//! Responsibility: declare the one canonical runtime constant for every approved diagnostic.
//! Does not own: rich metadata, allocation history, producer mappings, or rendering prose.
//! Boundary: this is the only module that converts approved nonzero numbers into producer identities.

use crate::diagnostics::{RegisteredDiagnosticCode, registered};

macro_rules! declare_diagnostic_codes {
    ($($name:ident = $code:literal;)*) => {
        $(
            #[doc = concat!("Registered diagnostic identity `", stringify!($name), "`.")]
            pub const $name: RegisteredDiagnosticCode = registered($code);
        )*

        /// Complete native-only inventory used to check the host catalogue bijection.
        #[cfg(not(target_arch = "wasm32"))]
        pub const ALL_REGISTERED_DIAGNOSTIC_CODES: &[RegisteredDiagnosticCode] = &[
            $($name,)*
        ];
    };
}

